  const opts = shuffle([t.a].concat(t.w), rnd); return { id, line: t.line, topic: t.topic, d: t.d, def: t.q, term: t.a, full: t.x, opts, answer: opts.indexOf(t.a), cat: t.topic, prompt: 'Choose the best answer.' };
