  (o.extra || []).forEach((t, i) => { const m = materialise(t, rnd, 'x' + i); if(m) pool.push(m); });
  GEN.forEach((g, gi) => { for(let k = 0, tries = 0; k < 3 && tries < 12; tries++){ const m = materialise(g(rnd), rnd, 'g' + gi + '_' + Math.floor(rnd() * 1e6)); if(m && m.opts.length === 4){ pool.push(m); k++; } } });
