  if(o.glossaryQs) o.glossaryQs.forEach(q => { const l = LINE_OF_CAT[q.cat] || 'sector'; pool.push({ id: 'l_' + q.term, line: l, topic: 'terms', d: TECH.indexOf(q.cat) >= 0 ? 3 : l === 'life' ? 1 : 2, def: q.def, term: q.term, full: q.full, opts: q.opts, answer: q.answer, cat: q.cat, prompt: 'Which term is this?' }); });
