  const seen = new Set(o.seen || []); const lv = o.level || 2;
  cand = shuffle(cand, rnd).map(q => ({ q, k: Math.abs(q.d - lv) + (seen.has(q.id) ? 0.6 : 0) + rnd() * 0.5 })).sort((a, b) => a.k - b.k).map(x => x.q);
